// MESA CLUB v5 · ajedrez, dominó, billar, monedas y skins · archivo de despliegue.
'use strict';
const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const zlib=require('node:zlib');
const payload='';
const bytes=Buffer.from(payload,'base64');
if(crypto.createHash('sha256').update(bytes).digest('hex')!=='7dab14f93281f981ef04f829ba997d85335f72a9645afc561d3c8d894adbd4f0')throw Error('Archivo dañado');
const contents=JSON.parse(zlib.brotliDecompressSync(bytes).toString('utf8'));
for(const [name,code] of Object.entries(contents)){
 if(!/^(server|chess|store|domino|pool|backup|migrate)\.js$|^public\/(index\.html|app\.js|styles\.css)$/.test(name))throw Error('Ruta inválida');
 const target=path.join(__dirname,name);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,code);
}
console.log('MESA CLUB v5 preparado con tres juegos y tienda de skins.');
const {server}=require('./server');
const {init,getStorage,shutdown}=require('./store');
init().then(()=>server.listen(Number(process.env.PORT)||3000,'0.0.0.0',()=>console.log('MESA CLUB online · almacenamiento: '+getStorage()))).catch(err=>{console.error('La base de datos no está lista:',err.message);process.exitCode=1;shutdown().catch(()=>{});server.close();});
